#include <stdio.h>

struct Vec2 { double x; double y; };

void translate(struct Vec2 *v, double dx, double dy) {
    v->x += dx;
    v->y += dy;
}

int main(void) {
    struct Vec2 p = {1.0, 2.0};
    printf("before: (%.1f, %.1f)\n", p.x, p.y);
    translate(&p, 3.0, 4.0);
    printf("after:  (%.1f, %.1f)\n", p.x, p.y);
    return 0;
}
